#include <stdio.h>

int solution(long long N) {
    char s[32];
    sprintf(s, "%lld", N);
    int maxLen = 1, curr = 1;
    for (int i = 1; s[i] != '\0'; i++) {
        if (s[i] < s[i]) curr++;
        else curr = 1;
        if (curr > maxLen) maxLen = curr;
    }
    return maxLen;
}

